/* ------------------------------------------------------------------ *
 * JSON tree builder (owned values, freed with kcl_json_free)          *
 * ------------------------------------------------------------------ */

static void* xalloc(size_t size)
{
    void* p = calloc(1, size);
    if (p == NULL) {
        printf("out of memory building a projected field\n");
        exit(1);
    }
    return p;
}

static char* xstrdup(const char* text)
{
    size_t len = strlen(text);
    char* copy = (char*)xalloc(len + 1);
    memcpy(copy, text, len + 1);
    return copy;
}

static kcl_json_value_t* jb_string(const char* text)
{
    kcl_json_value_t* v = (kcl_json_value_t*)xalloc(sizeof(*v));
    v->type = KCL_JSON_STRING;
    v->u.string.data = xstrdup(text != NULL ? text : "");
    v->u.string.length = strlen(v->u.string.data);
    return v;
}

static kcl_json_value_t* jb_number(double number)
{
    kcl_json_value_t* v = (kcl_json_value_t*)xalloc(sizeof(*v));
    v->type = KCL_JSON_NUMBER;
    v->u.number = number;
    return v;
}

static kcl_json_value_t* jb_bool(bool value)
{
    kcl_json_value_t* v = (kcl_json_value_t*)xalloc(sizeof(*v));
    v->type = KCL_JSON_BOOL;
    v->u.boolean = value;
    return v;
}

/* Slots needed to hold `count` items: the builder's arrays grow by
 * doubling from an initial four slots. */
static size_t jb_capacity(size_t count)
{
    size_t capacity = 4;
    while (capacity < count)
        capacity *= 2;
    return capacity;
}

static kcl_json_value_t* jb_array(void)
{
    kcl_json_value_t* v = (kcl_json_value_t*)xalloc(sizeof(*v));
    v->type = KCL_JSON_ARRAY;
    v->u.array.items = (kcl_json_value_t**)xalloc(jb_capacity(1) * sizeof(kcl_json_value_t*));
    v->u.array.count = 0;
    return v;
}

static kcl_json_value_t* jb_object(void)
{
    kcl_json_value_t* v = (kcl_json_value_t*)xalloc(sizeof(*v));
    v->type = KCL_JSON_OBJECT;
    v->u.object.keys = (char**)xalloc(jb_capacity(1) * sizeof(char*));
    v->u.object.values = (kcl_json_value_t**)xalloc(jb_capacity(1) * sizeof(kcl_json_value_t*));
    v->u.object.count = 0;
    return v;
}

/* Ownership of `item` moves to `arr`. */
static void jb_push(kcl_json_value_t* arr, kcl_json_value_t* item)
{
    size_t before = jb_capacity(arr->u.array.count);
    size_t after = jb_capacity(arr->u.array.count + 1);
    if (after > before)
        arr->u.array.items = (kcl_json_value_t**)realloc(arr->u.array.items, after * sizeof(kcl_json_value_t*));
    arr->u.array.items[arr->u.array.count++] = item;
}

/* Ownership of `value` moves to `obj`; `key` is copied. */
static void jb_put(kcl_json_value_t* obj, const char* key, kcl_json_value_t* value)
{
    size_t before = jb_capacity(obj->u.object.count);
    size_t after = jb_capacity(obj->u.object.count + 1);
    if (after > before) {
        obj->u.object.keys = (char**)realloc(obj->u.object.keys, after * sizeof(char*));
        obj->u.object.values = (kcl_json_value_t**)realloc(obj->u.object.values, after * sizeof(kcl_json_value_t*));
    }
    obj->u.object.keys[obj->u.object.count] = xstrdup(key != NULL ? key : "");
    obj->u.object.values[obj->u.object.count] = value;
    obj->u.object.count++;
}

/* ------------------------------------------------------------------ *
 * Canonical JSON rendering                                            *
 * ------------------------------------------------------------------ */

struct canon_sink {
    char* buffer;
    size_t size;
    size_t length;
    bool overflow;
};

static bool canon_putn(struct canon_sink* sink, const char* data, size_t len)
{
    if (sink->overflow)
        return false;
    if (sink->length + len >= sink->size) {
        sink->overflow = true;
        return false;
    }
    memcpy(sink->buffer + sink->length, data, len);
    sink->length += len;
    sink->buffer[sink->length] = '\0';
    return true;
}

static bool canon_puts(struct canon_sink* sink, const char* text)
{
    return canon_putn(sink, text, strlen(text));
}

static bool canon_printf(struct canon_sink* sink, const char* fmt, ...)
{
    va_list ap;
    int n;
    if (sink->overflow || sink->length >= sink->size)
        return false;
    va_start(ap, fmt);
    n = vsnprintf(sink->buffer + sink->length, sink->size - sink->length, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= sink->size - sink->length) {
        sink->overflow = true;
        return false;
    }
    sink->length += (size_t)n;
    return true;
}

/* Quoted, escaped JSON string — same escaping rules as the library's
 * kclm_sink_json_string, so a wrapper-rendered document round-trips
 * through parse and print unchanged. */
static bool canon_json_string(struct canon_sink* sink, const char* data, size_t len)
{
    static const char hex[] = "0123456789abcdef";
    size_t i;
    if (!canon_putn(sink, "\"", 1))
        return false;
    for (i = 0; i < len; i++) {
        unsigned char c = (unsigned char)data[i];
        const char* esc = NULL;
        char tmp[7];
        switch (c) {
        case '"':
            esc = "\\\"";
            break;
        case '\\':
            esc = "\\\\";
            break;
        case '\b':
            esc = "\\b";
            break;
        case '\f':
            esc = "\\f";
            break;
        case '\n':
            esc = "\\n";
            break;
        case '\r':
            esc = "\\r";
            break;
        case '\t':
            esc = "\\t";
            break;
        default:
            if (c < 0x20) {
                tmp[0] = '\\';
                tmp[1] = 'u';
                tmp[2] = '0';
                tmp[3] = '0';
                tmp[4] = hex[c >> 4];
                tmp[5] = hex[c & 0xf];
                tmp[6] = '\0';
                esc = tmp;
            }
            break;
        }
        if (esc != NULL) {
            if (!canon_puts(sink, esc))
                return false;
        } else if (!canon_putn(sink, (const char*)&data[i], 1)) {
            return false;
        }
    }
    return canon_putn(sink, "\"", 1);
}

struct canon_member {
    const char* key;
    const kcl_json_value_t* value;
};

static int canon_compare_members(const void* a, const void* b)
{
    const struct canon_member* ma = (const struct canon_member*)a;
    const struct canon_member* mb = (const struct canon_member*)b;
    return strcmp(ma->key, mb->key);
}

/* JSON numbers decode to double; the manifest and the wrapper-rendered
 * documents only carry small integral ones, which print without a
 * fractional part so `line = 2` never becomes `2.0`. */
static bool canon_number(struct canon_sink* sink, double number)
{
    long long integral;
    if (number >= -1e15 && number <= 1e15) {
        integral = (long long)number;
        if ((double)integral == number)
            return canon_printf(sink, "%lld", integral);
    }
    return canon_printf(sink, "%.17g", number);
}

static bool canon_value(struct canon_sink* sink, const kcl_json_value_t* v)
{
    size_t i;
    switch (v->type) {
    case KCL_JSON_NULL:
        return canon_puts(sink, "null");
    case KCL_JSON_BOOL:
        return canon_puts(sink, v->u.boolean ? "true" : "false");
    case KCL_JSON_NUMBER:
        return canon_number(sink, v->u.number);
    case KCL_JSON_STRING:
        return canon_json_string(sink, v->u.string.data, v->u.string.length);
    case KCL_JSON_ARRAY:
        if (!canon_putn(sink, "[", 1))
            return false;
        for (i = 0; i < v->u.array.count; i++) {
            if (i > 0 && !canon_putn(sink, ",", 1))
                return false;
            if (!canon_value(sink, v->u.array.items[i]))
                return false;
        }
        return canon_putn(sink, "]", 1);
    case KCL_JSON_OBJECT: {
        /* count can be zero (an empty projection); xalloc(0) may hand
         * back NULL, which the builder treats as out-of-memory. */
        struct canon_member* members = v->u.object.count > 0
            ? (struct canon_member*)xalloc(v->u.object.count * sizeof(struct canon_member))
            : NULL;
        size_t n = 0;
        bool status = true;
        for (i = 0; i < v->u.object.count; i++) {
            /* `filename` holds the absolute path of the file a KclType
             * was declared in: unpinnable, so dropped at every depth
             * (the manifest is generated through the same rule). */
            if (strcmp(v->u.object.keys[i], "filename") == 0)
                continue;
            members[n].key = v->u.object.keys[i];
            members[n].value = v->u.object.values[i];
            n++;
        }
        qsort(members, n, sizeof(struct canon_member), canon_compare_members);
        if (!canon_putn(sink, "{", 1))
            status = false;
        for (i = 0; status && i < n; i++) {
            if (i > 0 && !canon_putn(sink, ",", 1))
                status = false;
            if (status && !canon_json_string(sink, members[i].key, strlen(members[i].key)))
                status = false;
            if (status && !canon_putn(sink, ":", 1))
                status = false;
            if (status && !canon_value(sink, members[i].value))
                status = false;
        }
        if (status)
            status = canon_putn(sink, "}", 1);
        free(members);
        return status;
    }
    }
    return false;
}

/* Render `v` into `buffer` in the canonical form both sides of every
 * comparison go through. A top-level string stays raw — the generated
 * documents are dozens of lines long, and the mismatch report diffs
 * them line by line (lua's `render` makes the same choice). */
static bool canonical_render(const kcl_json_value_t* v, char* buffer, size_t size)
{
    struct canon_sink sink = { buffer, size, 0, false };
    buffer[0] = '\0';
    if (v->type == KCL_JSON_STRING)
        return canon_putn(&sink, v->u.string.data, v->u.string.length);
    return canon_value(&sink, v) && !sink.overflow;
}

/* ------------------------------------------------------------------ *
 * Manifest access helpers                                             *
 * ------------------------------------------------------------------ */

static const char* json_text(const kcl_json_value_t* v)
{
    if (v == NULL || v->type != KCL_JSON_STRING || v->u.string.data == NULL)
        return NULL;
    return v->u.string.data;
}

/* The C spelling of Jackson's `node.path(key).asText("")`: a missing or
 * non-string entry becomes the fallback, never a crash. */
static const char* json_field(const kcl_json_value_t* obj, const char* key, const char* fallback)
{
    const char* text = json_text(kcl_json_object_get(obj, key));
    return text != NULL ? text : fallback;
}

static bool json_flag(const kcl_json_value_t* obj, const char* key, bool fallback)
{
    const kcl_json_value_t* v = kcl_json_object_get(obj, key);
    if (v == NULL)
        return fallback;
    if (v->type == KCL_JSON_BOOL)
        return v->u.boolean;
    if (v->type == KCL_JSON_NUMBER)
        return v->u.number != 0.0;
    return fallback;
}

/* Copy the string entries of `obj[key]` into `out`. Returns how many were
 * written, capped at `max`; entries are `""` when the manifest holds a
 * non-string, matching `asText()`. */
static size_t json_string_list(const kcl_json_value_t* obj, const char* key, const char** out, size_t max)
{
    const kcl_json_value_t* arr = kcl_json_object_get(obj, key);
    size_t n = kcl_json_array_length(arr);
    if (n > max)
        n = max;
    for (size_t i = 0; i < n; ++i) {
        const char* text = json_text(kcl_json_array_get(arr, i));
        out[i] = text != NULL ? text : "";
    }
    return n;
}

/* The manifest pins TestCaseInfo.duration as a decimal string ("1500");
 * struct KclTestCaseInfo carries it as uint64 microseconds. */
static uint64_t json_duration(const kcl_json_value_t* v)
{
    const char* text = json_text(v);
    if (text != NULL)
        return strtoull(text, NULL, 10);
    if (v != NULL && v->type == KCL_JSON_NUMBER)
        return (uint64_t)v->u.number;
    return 0;
}

/* ------------------------------------------------------------------ *
 * Path resolution and scratch copies                                  *
 * ------------------------------------------------------------------ */

/* Recursively copy `src` to `dest` (real copies, never links:
 * KclService.OverrideFile writes through the path it is handed, and a
 * link would send that write back into the repository). */
static bool copy_tree(const char* src, const char* dest)
{
    DIR* dir = opendir(src);
    struct dirent* entry;
    bool status = true;
    if (dir == NULL)
        return false;
    if (mkdir(dest, 0755) != 0 && errno != EEXIST) {
        closedir(dir);
        return false;
    }
    while ((entry = readdir(dir)) != NULL && status) {
        char from[PATH_MAX];
        char to[PATH_MAX];
        struct stat st;
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        snprintf(from, sizeof(from), "%s/%s", src, entry->d_name);
        snprintf(to, sizeof(to), "%s/%s", dest, entry->d_name);
        if (stat(from, &st) != 0) {
            status = false;
            break;
        }
        if (S_ISDIR(st.st_mode))
            status = copy_tree(from, to);
        else {
            FILE* in = fopen(from, "rb");
            FILE* out = NULL;
            char chunk[8192];
            size_t n;
            if (in == NULL) {
                status = false;
                break;
            }
            out = fopen(to, "wb");
            if (out == NULL) {
                fclose(in);
                status = false;
                break;
            }
            while ((n = fread(chunk, 1, sizeof(chunk), in)) > 0) {
                if (fwrite(chunk, 1, n, out) != n) {
                    status = false;
                    break;
                }
            }
            fclose(in);
            fclose(out);
        }
    }
    closedir(dir);
    return status;
}

/* Recursively delete `path`. The scratch tree only ever holds copies
 * this runner made, so a plain recursive delete is enough. */
static bool remove_tree(const char* path)
{
    DIR* dir = opendir(path);
    struct dirent* entry;
    bool status = true;
    struct stat st;
    if (dir == NULL)
        return remove(path) == 0;
    while ((entry = readdir(dir)) != NULL && status) {
        char child[PATH_MAX];
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        snprintf(child, sizeof(child), "%s/%s", path, entry->d_name);
        if (stat(child, &st) != 0) {
            status = false;
            break;
        }
        if (S_ISDIR(st.st_mode))
            status = remove_tree(child);
        else
            status = remove(child) == 0;
    }
    closedir(dir);
    if (!status)
        return false;
    return remove(path) == 0;
}

/* Copy `testdata/<template>` to a fresh directory under $TMPDIR and
 * return the path of `tail` inside the copy. `rest` is the part after
 * `scratch:`, so `scratch:override/main.k` names main.k inside a copy of
 * the override template and `scratch:lint` names the copied directory
 * itself. Each call gets its own root, so two cases — and two runs —
 * never observe each other's writes. Note that a case naming the same
 * template twice (load_settings_files names one in both work_dir and
 * files) gets two copies, exactly as the python, lua and java runners
 * do. */
static const char* make_scratch(struct runner* r, const char* rest)
{
    const char* slash = strchr(rest, '/');
    size_t template_len = slash != NULL ? (size_t)(slash - rest) : strlen(rest);
    const char* tail = slash != NULL ? slash + 1 : "";
    const char* tmpdir = getenv("TMPDIR");
    char src[PATH_MAX];
    char dest[PATH_MAX];
    char* root;
    if (template_len == 0 || scratch_root_count >= CONSISTENCY_MAX_LIST)
        return NULL;
    if (tmpdir == NULL || tmpdir[0] == '\0')
        tmpdir = "/tmp";
    snprintf(src, sizeof(src), "%s/tests/consistency/testdata/%.*s", r->repo_root, (int)template_len, rest);
    root = scratch_roots[scratch_root_count];
    snprintf(root, PATH_MAX, "%s/kcl-consistency-XXXXXX", tmpdir);
    if (mkdtemp(root) == NULL)
        return NULL;
    snprintf(dest, sizeof(dest), "%s/%.*s", root, (int)template_len, rest);
    if (!copy_tree(src, dest))
        return NULL;
    if (tail[0] != '\0')
        snprintf(scratch_paths[scratch_root_count], PATH_MAX, "%s/%s", dest, tail);
    else
        snprintf(scratch_paths[scratch_root_count], PATH_MAX, "%s", dest);
    scratch_root_count++;
    return scratch_paths[scratch_root_count - 1];
}

/* Delete every scratch copy made so far; called after each case so a
 * run leaves nothing behind, passed or failed. */
static void cleanup_scratch(void)
{
    while (scratch_root_count > 0) {
        scratch_root_count--;
        remove_tree(scratch_roots[scratch_root_count]);
    }
}

/* Resolve one manifest path entry: a `scratch:` marker is copied and
 * replaced by the copy's path, an absolute path is kept as-is, and a
 * repo-relative one is made absolute against `r->repo_root` (the core
 * resolves relative paths against its own working directory, so every
 * relative entry has to be made absolute first). Returns `buf` holding
 * the composed path, a pointer into stable storage (the manifest text
 * or the scratch region), or NULL when the scratch copy failed. */
static const char* resolve_path(struct runner* r, const char* path, char* buf, size_t buf_size)
{
    if (strncmp(path, SCRATCH_PREFIX, strlen(SCRATCH_PREFIX)) == 0)
        return make_scratch(r, path + strlen(SCRATCH_PREFIX));
    if (path[0] == '/')
        return path;
    if (snprintf(buf, buf_size, "%s/%s", r->repo_root, path) >= (int)buf_size)
        return NULL;
    return buf;
}

/* Resolve `obj[key]` as a list of paths into `out`, composing repo-relative
 * and scratch entries into `scratch`/`resolved`. */
static size_t json_resolved_paths(struct runner* r, const kcl_json_value_t* obj, const char* key,
    const char** out, char (*scratch)[PATH_MAX], size_t max)
{
    const kcl_json_value_t* arr = kcl_json_object_get(obj, key);
    size_t n = kcl_json_array_length(arr);
    if (n > max)
        n = max;
    for (size_t i = 0; i < n; ++i) {
        const char* text = json_text(kcl_json_array_get(arr, i));
        const char* resolved = resolve_path(r, text != NULL ? text : "", scratch[i], PATH_MAX);
        out[i] = resolved != NULL ? resolved : "";
    }
    return n;
}

/* ------------------------------------------------------------------ *
 * Reporting                                                           *
 * ------------------------------------------------------------------ */

/* Line diff, same shape as the java `ConsistencyTest.diff` and go
 * `diffLines`: two spaces for a matching line, `- expected` / `+ actual`
 * for the rest.
 */
static void print_diff(const char* expected, const char* actual)
{
    printf("      --- expected\n      +++ actual\n");
    const char* e = expected;
    const char* a = actual;
    while (*e != '\0' || *a != '\0') {
        const char* eol = strchr(e, '\n');
        const char* aol = strchr(a, '\n');
        size_t elen = eol != NULL ? (size_t)(eol - e) + 1 : strlen(e);
        size_t alen = aol != NULL ? (size_t)(aol - a) + 1 : strlen(a);
        if (elen == alen && memcmp(e, a, elen) == 0)
            printf("        %.*s%s", (int)elen, e, eol != NULL ? "" : "\n");
        else {
            if (elen > 0)
                printf("      - %.*s%s", (int)elen, e, eol != NULL ? "" : "\n");
            if (alen > 0)
                printf("      + %.*s%s", (int)alen, a, aol != NULL ? "" : "\n");
        }
        e = eol != NULL ? eol + 1 : e + elen;
        a = aol != NULL ? aol + 1 : a + alen;
    }
}

/* Compare every field the case's `expect` object pins: the manifest
 * value and the projection both render through canonical_render, so the
 * two sides can only disagree on content, never on key order or
 * dialect. A pinned field the projection does not produce is a failure
 * rather than a skip. */
static bool compare_fields(const char* case_name, const kcl_json_value_t* expect,
    const struct projected_field* fields, size_t field_count,
    char* expect_buffer, size_t expect_buffer_size,
    char* actual_buffer, size_t actual_buffer_size)
{
    bool ok = true;
    for (size_t i = 0; i < expect->u.object.count; ++i) {
        const char* key = expect->u.object.keys[i];
        const kcl_json_value_t* want = expect->u.object.values[i];
        const kcl_json_value_t* got = NULL;
        for (size_t j = 0; j < field_count; ++j) {
            if (strcmp(fields[j].name, key) == 0) {
                got = fields[j].value;
                break;
            }
        }
        if (got == NULL) {
            printf("    case `%s` expects field `%s`, which the projection does not produce\n", case_name, key);
            ok = false;
            continue;
        }
        if (!canonical_render(want, expect_buffer, expect_buffer_size)
            || !canonical_render(got, actual_buffer, actual_buffer_size)) {
            printf("    case `%s` field `%s`: the canonical rendering overflows its buffer\n", case_name, key);
            ok = false;
            continue;
        }
        if (strcmp(expect_buffer, actual_buffer) != 0) {
            printf("    case `%s` field `%s` mismatch:\n", case_name, key);
            print_diff(expect_buffer, actual_buffer);
            ok = false;
        }
    }
    return ok;
}

/* Mirrors go's isUnavailableRPCError: a core that does not register the
 * rpc may answer with an "unknown method"-style error rather than dropping
 * it from ListMethod.
 */
static bool is_unavailable_rpc_error(const char* message)
{
    return strstr(message, "unknown method") != NULL
        || strstr(message, "not implemented") != NULL
        || strstr(message, "unimplemented") != NULL
        || strstr(message, "invalid rpc") != NULL;
}

/* ------------------------------------------------------------------ *
 * Projection utilities                                                *
 * ------------------------------------------------------------------ */

/* Entries of a top-level array in an AST document, or 0 when the
 * document is empty or does not parse — "the binding attached no tree
 * at all" and "the tree is malformed" are the same observation to a
 * shape-pinning case. `ParseFile` answers a bare `Module`, so the
 * statements are at `body`; `ParseProgram` answers a `pkgs` document
 * keyed by package path, hence the optional `subkey`. */
static size_t json_tree_len(const char* doc, const char* key, const char* subkey)
{
    kcl_json_value_t* root;
    const kcl_json_value_t* node;
    size_t count;
    if (doc[0] == '\0')
        return 0;
    root = kcl_json_parse(doc);
    if (root == NULL)
        return 0;
    node = kcl_json_object_get(root, key);
    if (subkey != NULL)
        node = kcl_json_object_get(node, subkey);
    count = kcl_json_array_length(node);
    kcl_json_free(root);
    return count;
}

/* Entries of a wrapper-rendered JSON document (error lists, scopes and
 * symbols maps); an empty or unparsable document counts as 0. */
static size_t json_array_count(const char* text)
{
    kcl_json_value_t* root;
    size_t count;
    if (text[0] == '\0')
        return 0;
    root = kcl_json_parse(text);
    if (root == NULL)
        return 0;
    count = kcl_json_array_length(root);
    kcl_json_free(root);
    return count;
}

/* Lines of a '\n'-joined collector buffer; an empty buffer is zero
 * entries. Collector entries never carry newlines themselves. */
static size_t count_lines(const char* text)
{
    size_t count = 0;
    size_t length = strlen(text);
    for (size_t i = 0; i < length; ++i) {
        if (text[i] == '\n')
            count++;
    }
    if (length > 0 && text[length - 1] != '\n')
        count++;
    return count;
}

static kcl_json_value_t* split_lines_json(const char* text)
{
    kcl_json_value_t* arr = jb_array();
    const char* line = text;
    while (*line != '\0') {
        const char* eol = strchr(line, '\n');
        size_t len = eol != NULL ? (size_t)(eol - line) : strlen(line);
        char* copy = (char*)xalloc(len + 1);
        memcpy(copy, line, len);
        copy[len] = '\0';
        jb_push(arr, jb_string(copy));
        free(copy);
        line = eol != NULL ? eol + 1 : line + len;
    }
    return arr;
}

static const char* path_basename(const char* path)
{
    const char* slash = strrchr(path, '/');
    return slash != NULL ? slash + 1 : path;
}

static int compare_string_items(const void* a, const void* b)
{
    const kcl_json_value_t* va = *(const kcl_json_value_t* const*)a;
    const kcl_json_value_t* vb = *(const kcl_json_value_t* const*)b;
    return strcmp(va->u.string.data, vb->u.string.data);
}

static void sort_string_array(kcl_json_value_t* arr)
{
    qsort(arr->u.array.items, arr->u.array.count, sizeof(kcl_json_value_t*), compare_string_items);
}

static int compare_pair_items(const void* a, const void* b)
{
    const kcl_json_value_t* va = *(const kcl_json_value_t* const*)a;
    const kcl_json_value_t* vb = *(const kcl_json_value_t* const*)b;
    const char* ka = va->u.array.count > 0 ? va->u.array.items[0]->u.string.data : "";
    const char* kb = vb->u.array.count > 0 ? vb->u.array.items[0]->u.string.data : "";
    return strcmp(ka, kb);
}

/* The wrapper renders protobuf maps as JSON arrays of {"key", "value"}
 * entries; the manifest pins them as plain JSON objects. Convert
 * recursively — an array whose every element is an object with a string
 * `key` member and a `value` member becomes an object keyed by `key` —
 * and copy, so the result is an owned tree. KclType documents never
 * carry a [key, value]-shaped array that is not a map rendering, so the
 * rule is exact for the schema-mapping cases it serves. */
static bool json_entry_shape(const kcl_json_value_t* item, const char** key_out)
{
    const kcl_json_value_t* key;
    if (item == NULL || item->type != KCL_JSON_OBJECT)
        return false;
    key = kcl_json_object_get(item, "key");
    if (key == NULL || key->type != KCL_JSON_STRING || kcl_json_object_get(item, "value") == NULL)
        return false;
    *key_out = key->u.string.data;
    return true;
}

static kcl_json_value_t* entries_to_object(const kcl_json_value_t* node)
{
    size_t i;
    if (node == NULL)
        return jb_object();
    switch (node->type) {
    case KCL_JSON_NULL: {
        kcl_json_value_t* v = (kcl_json_value_t*)xalloc(sizeof(*v));
        v->type = KCL_JSON_NULL;
        return v;
    }
    case KCL_JSON_BOOL:
        return jb_bool(node->u.boolean);
    case KCL_JSON_NUMBER:
        return jb_number(node->u.number);
    case KCL_JSON_STRING:
        return jb_string(node->u.string.data);
    case KCL_JSON_ARRAY: {
        bool all_entries = node->u.array.count > 0;
        for (i = 0; i < node->u.array.count; ++i) {
            const char* key;
            if (!json_entry_shape(node->u.array.items[i], &key)) {
                all_entries = false;
                break;
            }
        }
        if (all_entries) {
            kcl_json_value_t* obj = jb_object();
            for (i = 0; i < node->u.array.count; ++i) {
                const char* key;
                json_entry_shape(node->u.array.items[i], &key);
                jb_put(obj, key, entries_to_object(kcl_json_object_get(node->u.array.items[i], "value")));
            }
            return obj;
        }
        {
            kcl_json_value_t* arr = jb_array();
            for (i = 0; i < node->u.array.count; ++i)
                jb_push(arr, entries_to_object(node->u.array.items[i]));
            return arr;
        }
    }
    case KCL_JSON_OBJECT: {
        kcl_json_value_t* obj = jb_object();
        for (i = 0; i < node->u.object.count; ++i)
            jb_put(obj, node->u.object.keys[i], entries_to_object(node->u.object.values[i]));
        return obj;
    }
    }
    return jb_object();
}

/* The wrapper renders ListVariables.variables as an array of
 * {"key": spec, "value": {"variables": [{"value": ...}, ...]}} entries;
 * the manifest pins {spec: [variable values]}. */
static kcl_json_value_t* project_variable_values(const char* variables_doc)
{
    kcl_json_value_t* root;
    kcl_json_value_t* values = jb_object();
    size_t i, j;
    if (variables_doc[0] == '\0')
        return values;
    root = kcl_json_parse(variables_doc);
    if (root == NULL)
        return values;
    if (root->type == KCL_JSON_ARRAY) {
        for (i = 0; i < root->u.array.count; ++i) {
            const kcl_json_value_t* entry = root->u.array.items[i];
            const char* spec = json_field(entry, "key", "");
            const kcl_json_value_t* vars = kcl_json_object_get(kcl_json_object_get(entry, "value"), "variables");
            size_t var_count = kcl_json_array_length(vars);
            kcl_json_value_t* items = jb_array();
            for (j = 0; j < var_count; ++j)
                jb_push(items, jb_string(json_field(kcl_json_array_get(vars, j), "value", "")));
            jb_put(values, spec, items);
        }
    }
    kcl_json_free(root);
    return values;
}

/* ------------------------------------------------------------------ *
 * Args builders                                                       *
 * ------------------------------------------------------------------ */

/* Fill `request` from the manifest's exec_args node. work_dir is
 * resolved (scratch/absolute/repo-relative) into `work_dir_out`,
 * k_code_list and overrides pass through verbatim, and k_filename_list
 * entries are joined onto the resolved work_dir — the core resolves
 * filenames against the process working directory rather than work_dir,
 * so a relative entry has to be made absolute here or it will not
 * survive being run from another directory (same rule as the lua
 * runner). Returns false when a scratch copy fails. */
static bool json_exec_args(struct runner* r, const kcl_json_value_t* args,
    struct KclExecProgramArgs* request, char* work_dir_out, size_t work_dir_out_size)
{
    const char* work_dir = json_field(args, "work_dir", "");
    const kcl_json_value_t* filenames;
    size_t count;
    memset(request, 0, sizeof(*request));
    if (work_dir[0] != '\0') {
        if (resolve_path(r, work_dir, work_dir_out, work_dir_out_size) == NULL)
            return false;
        request->work_dir = work_dir_out;
    }
    request->k_code_list = exec_code_list;
    request->k_code_count = json_string_list(args, "k_code_list", exec_code_list, CONSISTENCY_MAX_LIST);
    request->overrides = exec_override_list;
    request->override_count = json_string_list(args, "overrides", exec_override_list, CONSISTENCY_MAX_LIST);
    request->sort_keys = json_flag(args, "sort_keys", false);
    filenames = kcl_json_object_get(args, "k_filename_list");
    count = kcl_json_array_length(filenames);
    if (count > CONSISTENCY_MAX_LIST)
        count = CONSISTENCY_MAX_LIST;
    for (size_t i = 0; i < count; ++i) {
        const char* name = json_text(kcl_json_array_get(filenames, i));
        const char* resolved;
        if (name == NULL)
            name = "";
        if (name[0] == '/' || request->work_dir == NULL) {
            exec_filename_list[i] = name;
            continue;
        }
        snprintf(exec_filename_scratch[i], PATH_MAX, "%s/%s", request->work_dir, name);
        resolved = exec_filename_scratch[i];
        exec_filename_list[i] = resolved;
    }
    request->k_filename_list = exec_filename_list;
    request->k_filename_count = count;
    return true;
}

/* Fill `request` from a manifest parse_args node: paths are resolved
 * (scratch/absolute/repo-relative), sources are labels the AST records
 * and are forwarded verbatim. */
static bool json_parse_args(struct runner* r, const kcl_json_value_t* args,
    struct KclParseProgramArgs* request)
{
    memset(request, 0, sizeof(*request));
    request->paths = parse_path_list;
    request->path_count = json_resolved_paths(r, args, "paths", parse_path_list, parse_path_scratch, CONSISTENCY_MAX_LIST);
    request->sources = parse_source_list;
    request->source_count = json_string_list(args, "sources", parse_source_list, CONSISTENCY_MAX_LIST);
    for (size_t i = 0; i < request->path_count; ++i) {
        if (parse_path_list[i][0] == '\0')
            return false;
    }
    return true;
}

/* ------------------------------------------------------------------ *
 * Hand-rolled RPC calls                                               *
 * ------------------------------------------------------------------ */

/* The ExecProgram cases drive k_code_list and overrides, which the
 * kcl_exec_program wrapper does not surface, so the Args message is
 * built here with the same helper the Generate* wrappers use and
 * dispatched by hand — the same thing the wrapper itself does.
 */
static bool call_exec_program(struct runner* r, const kcl_json_value_t* args,
    char* yaml_out, size_t yaml_size, char* json_out, size_t json_size, char* err_out, size_t err_size)
{
    struct KclExecProgramArgs request;
    struct KclStringList filenames = { 0 };
    struct KclStringList codes = { 0 };
    struct KclStringList overrides = { 0 };
    struct RepeatedExternalPkg pkgs = { 0 };
    uint8_t* buffer = NULL;
    uint8_t* result_buffer = NULL;
    uint8_t* yaml_buffer = NULL;
    uint8_t* json_buffer = NULL;
    bool status = false;
    err_out[0] = '\0';
    if (!json_exec_args(r, args, &request, work_dir_scratch, sizeof(work_dir_scratch)))
        goto done;
    buffer = (uint8_t*)malloc(BUFFER_SIZE);
    result_buffer = (uint8_t*)malloc(BUFFER_SIZE);
    yaml_buffer = (uint8_t*)calloc(1, BUFFER_SIZE);
    json_buffer = (uint8_t*)calloc(1, BUFFER_SIZE);
    if (buffer == NULL || result_buffer == NULL || yaml_buffer == NULL || json_buffer == NULL)
        goto done;

    ExecProgramArgs exec_args = ExecProgramArgs_init_zero;
    if (!kcl_bind_exec_program_args(&exec_args, &request, &filenames, &codes, &overrides, &pkgs))
        goto done;

    pb_ostream_t stream = pb_ostream_from_buffer(buffer, BUFFER_SIZE);
    if (!pb_encode(&stream, ExecProgramArgs_fields, &exec_args))
        goto done;

    size_t result_length = kcl_call("KclService.ExecProgram", buffer, stream.bytes_written, result_buffer);
    if (check_error_prefix(result_buffer)) {
        kcl_copy_string(err_out, err_size, result_buffer);
        goto done;
    }

    pb_istream_t istream = pb_istream_from_buffer(result_buffer, result_length);
    ExecProgramResult result = ExecProgramResult_init_default;
    result.yaml_result.funcs.decode = decode_string;
    result.yaml_result.arg = yaml_buffer;
    result.json_result.funcs.decode = decode_string;
    result.json_result.arg = json_buffer;
    if (!pb_decode(&istream, ExecProgramResult_fields, &result))
        goto done;

    kcl_copy_string(yaml_out, yaml_size, yaml_buffer);
    kcl_copy_string(json_out, json_size, json_buffer);
    status = true;

done:
    free(buffer);
    free(result_buffer);
    free(yaml_buffer);
    free(json_buffer);
    kcl_string_list_free(&filenames);
    kcl_string_list_free(&codes);
    kcl_string_list_free(&overrides);
    return status;
}

/* ParseFile/ParseProgram/ListOptions take their program in `source` /
 * `sources`, which the typed wrappers do not surface, so their Args
 * messages are built here by hand. The decoders are the library's own
 * (kcl_decode_string_list, kcl_decode_error_list_json,
 * kcl_decode_option_help_list).
 */
static bool call_parse_file(const kcl_json_value_t* args,
    char* ast_out, size_t ast_size, char* deps_out, size_t deps_size,
    char* errors_out, size_t errors_size, char* err_out, size_t err_size)
{
    uint8_t* buffer = (uint8_t*)malloc(BUFFER_SIZE);
    uint8_t* result_buffer = (uint8_t*)malloc(BUFFER_SIZE);
    bool status = false;
    if (buffer == NULL || result_buffer == NULL)
        goto done;
    /* decode_string decodes into a BUFFER_SIZE byte buffer; the callers
     * hand ast_out a result_primary slice, so ast_size is documentation. */
    (void)ast_size;

    const char* path = json_field(args, "path", "");
    const char* source = json_field(args, "source", "");
    ParseFileArgs pf_args = ParseFileArgs_init_zero;
    pf_args.path.funcs.encode = encode_string;
    pf_args.path.arg = (void*)path;
    pf_args.source.funcs.encode = encode_string;
    pf_args.source.arg = (void*)source;

    pb_ostream_t stream = pb_ostream_from_buffer(buffer, BUFFER_SIZE);
    if (!pb_encode(&stream, ParseFileArgs_fields, &pf_args))
        goto done;

    size_t result_length = kcl_call("KclService.ParseFile", buffer, stream.bytes_written, result_buffer);
    if (check_error_prefix(result_buffer)) {
        kcl_copy_string(err_out, err_size, result_buffer);
        goto done;
    }

    pb_istream_t istream = pb_istream_from_buffer(result_buffer, result_length);
    ParseFileResult result = ParseFileResult_init_default;
    struct KclStringListCollector deps_collector = { .buffer = deps_out, .size = deps_size, .length = 0 };
    struct KclJsonSink errors_sink;
    kcl_json_sink_init(&errors_sink, errors_out, errors_size);
    errors_sink.auto_array = true;
    result.ast_json.funcs.decode = decode_string;
    result.ast_json.arg = ast_out;
    result.deps.funcs.decode = kcl_decode_string_list;
    result.deps.arg = &deps_collector;
    result.errors.funcs.decode = kcl_decode_error_list_json;
    result.errors.arg = &errors_sink;
    if (!pb_decode(&istream, ParseFileResult_fields, &result))
        goto done;
    if (!kcl_json_sink_finish(&errors_sink))
        goto done;
    status = true;

done:
    free(buffer);
    free(result_buffer);
    return status;
}

static bool call_parse_program(const kcl_json_value_t* args,
    char* ast_out, size_t ast_size, char* paths_out, size_t paths_size,
    char* errors_out, size_t errors_size, char* err_out, size_t err_size)
{
    size_t source_count = json_string_list(args, "sources", parse_source_list, CONSISTENCY_MAX_LIST);
    struct Buffer* source_bufs = NULL;
    struct Buffer** source_ptrs = NULL;
    uint8_t* buffer = NULL;
    uint8_t* result_buffer = NULL;
    bool status = false;
    (void)ast_size; /* see call_parse_file */
    if (source_count > 0) {
        source_bufs = (struct Buffer*)malloc(source_count * sizeof(struct Buffer));
        source_ptrs = (struct Buffer**)malloc(source_count * sizeof(struct Buffer*));
        if (source_bufs == NULL || source_ptrs == NULL)
            goto done;
        for (size_t i = 0; i < source_count; ++i) {
            source_bufs[i].buffer = parse_source_list[i];
            source_bufs[i].len = strlen(parse_source_list[i]);
            source_ptrs[i] = &source_bufs[i];
        }
    }
    buffer = (uint8_t*)malloc(BUFFER_SIZE);
    result_buffer = (uint8_t*)malloc(BUFFER_SIZE);
    if (buffer == NULL || result_buffer == NULL)
        goto done;

    struct RepeatedString strs = { .repeated = source_ptrs, .index = 0, .saved_index = 0, .max_size = source_count };
    ParseProgramArgs pp_args = ParseProgramArgs_init_zero;
    pp_args.sources.funcs.encode = encode_str_list;
    pp_args.sources.arg = &strs;

    pb_ostream_t stream = pb_ostream_from_buffer(buffer, BUFFER_SIZE);
    if (!pb_encode(&stream, ParseProgramArgs_fields, &pp_args))
        goto done;

    size_t result_length = kcl_call("KclService.ParseProgram", buffer, stream.bytes_written, result_buffer);
    if (check_error_prefix(result_buffer)) {
        kcl_copy_string(err_out, err_size, result_buffer);
        goto done;
    }

    pb_istream_t istream = pb_istream_from_buffer(result_buffer, result_length);
    ParseProgramResult result = ParseProgramResult_init_default;
    struct KclStringListCollector paths_collector = { .buffer = paths_out, .size = paths_size, .length = 0 };
    struct KclJsonSink errors_sink;
    kcl_json_sink_init(&errors_sink, errors_out, errors_size);
    errors_sink.auto_array = true;
    result.ast_json.funcs.decode = decode_string;
    result.ast_json.arg = ast_out;
    result.paths.funcs.decode = kcl_decode_string_list;
    result.paths.arg = &paths_collector;
    result.errors.funcs.decode = kcl_decode_error_list_json;
    result.errors.arg = &errors_sink;
    if (!pb_decode(&istream, ParseProgramResult_fields, &result))
        goto done;
    if (!kcl_json_sink_finish(&errors_sink))
        goto done;
    status = true;

done:
    free(buffer);
    free(result_buffer);
    free(source_bufs);
    free(source_ptrs);
    return status;
}

static bool call_list_options(const kcl_json_value_t* args, size_t* option_count,
    char* err_out, size_t err_size)
{
    size_t source_count = json_string_list(args, "sources", parse_source_list, CONSISTENCY_MAX_LIST);
    struct Buffer* source_bufs = NULL;
    struct Buffer** source_ptrs = NULL;
    uint8_t* buffer = NULL;
    uint8_t* result_buffer = NULL;
    bool status = false;
    if (source_count > 0) {
        source_bufs = (struct Buffer*)malloc(source_count * sizeof(struct Buffer));
        source_ptrs = (struct Buffer**)malloc(source_count * sizeof(struct Buffer*));
        if (source_bufs == NULL || source_ptrs == NULL)
            goto done;
        for (size_t i = 0; i < source_count; ++i) {
            source_bufs[i].buffer = parse_source_list[i];
            source_bufs[i].len = strlen(parse_source_list[i]);
            source_ptrs[i] = &source_bufs[i];
        }
    }
    buffer = (uint8_t*)malloc(BUFFER_SIZE);
    result_buffer = (uint8_t*)malloc(BUFFER_SIZE);
    if (buffer == NULL || result_buffer == NULL)
        goto done;

    struct RepeatedString strs = { .repeated = source_ptrs, .index = 0, .saved_index = 0, .max_size = source_count };
    ParseProgramArgs lo_args = ParseProgramArgs_init_zero;
    lo_args.sources.funcs.encode = encode_str_list;
    lo_args.sources.arg = &strs;

    pb_ostream_t stream = pb_ostream_from_buffer(buffer, BUFFER_SIZE);
    if (!pb_encode(&stream, ParseProgramArgs_fields, &lo_args))
        goto done;

    size_t result_length = kcl_call("KclService.ListOptions", buffer, stream.bytes_written, result_buffer);
    if (check_error_prefix(result_buffer)) {
        kcl_copy_string(err_out, err_size, result_buffer);
        goto done;
    }

    pb_istream_t istream = pb_istream_from_buffer(result_buffer, result_length);
    ListOptionsResult result = ListOptionsResult_init_default;
    struct KclOptionHelpCollector collector = { .items = option_help, .max_count = CONSISTENCY_MAX_LIST, .count = 0 };
    result.options.funcs.decode = kcl_decode_option_help_list;
    result.options.arg = &collector;
    if (!pb_decode(&istream, ListOptionsResult_fields, &result))
        goto done;
    *option_count = collector.count;
    status = true;

done:
    free(buffer);
    free(result_buffer);
    free(source_bufs);
    free(source_ptrs);
    return status;
}

/* GetSchemaTypeMapping(UnderPath) nest ExecProgramArgs, which carries
 * k_code_list — a field the typed wrappers do not surface — so the
 * request is encoded here exactly the way kcl_get_schema_type_mapping
 * does it, and the mapping decoded through the library's entry
 * renderers.
 */
static bool call_schema_mapping(struct runner* r, const char* rpc, const kcl_json_value_t* args,
    char* mapping_out, size_t mapping_size, char* err_out, size_t err_size)
{
    struct KclExecProgramArgs request;
    struct KclStringList filenames = { 0 };
    struct KclStringList codes = { 0 };
    struct KclStringList overrides = { 0 };
    struct RepeatedExternalPkg pkgs = { 0 };
    uint8_t* buffer = NULL;
    uint8_t* result_buffer = NULL;
    bool status = false;
    const char* schema_name = json_field(args, "schema_name", "");
    if (!json_exec_args(r, kcl_json_object_get(args, "exec_args"), &request, work_dir_scratch, sizeof(work_dir_scratch)))
        goto done;
    buffer = (uint8_t*)malloc(BUFFER_SIZE);
    result_buffer = (uint8_t*)malloc(BUFFER_SIZE);
    if (buffer == NULL || result_buffer == NULL)
        goto done;

    ExecProgramArgs exec_args = ExecProgramArgs_init_zero;
    if (!kcl_bind_exec_program_args(&exec_args, &request, &filenames, &codes, &overrides, &pkgs))
        goto done;

    pb_ostream_t stream = pb_ostream_from_buffer(buffer, BUFFER_SIZE);
    if (!kcl_encode_tagged_submsg(&stream, GetSchemaTypeMappingArgs_exec_args_tag, ExecProgramArgs_fields, &exec_args))
        goto done;
    if (schema_name[0] != '\0' && !kcl_encode_tagged_string(&stream, GetSchemaTypeMappingArgs_schema_name_tag, schema_name))
        goto done;

    size_t result_length = kcl_call(rpc, buffer, stream.bytes_written, result_buffer);
    if (check_error_prefix(result_buffer)) {
        kcl_copy_string(err_out, err_size, result_buffer);
        goto done;
    }

    pb_istream_t istream = pb_istream_from_buffer(result_buffer, result_length);
    struct KclJsonSink mapping_sink;
    kcl_json_sink_init(&mapping_sink, mapping_out, mapping_size);
    mapping_sink.auto_array = true;
    if (strcmp(rpc, "KclService.GetSchemaTypeMappingUnderPath") == 0) {
        GetSchemaTypeMappingUnderPathResult result = GetSchemaTypeMappingUnderPathResult_init_default;
        result.schema_type_mapping.funcs.decode = kcl_decode_schema_types_map_json;
        result.schema_type_mapping.arg = &mapping_sink;
        if (!pb_decode(&istream, GetSchemaTypeMappingUnderPathResult_fields, &result))
            goto done;
    } else {
        GetSchemaTypeMappingResult result = GetSchemaTypeMappingResult_init_default;
        result.schema_type_mapping.funcs.decode = kcl_decode_kcltype_map_json;
        result.schema_type_mapping.arg = &mapping_sink;
        if (!pb_decode(&istream, GetSchemaTypeMappingResult_fields, &result))
            goto done;
    }
    if (!kcl_json_sink_finish(&mapping_sink))
        goto done;
    status = true;

done:
    free(buffer);
    free(result_buffer);
    kcl_string_list_free(&filenames);
    kcl_string_list_free(&codes);
    kcl_string_list_free(&overrides);
    return status;
}

/* LintPath answers a list of diagnostics; the manifest pins a count and
 * a has_result flag, so the entries are counted on the wire instead of
 * being joined into lines that a diagnostic with an embedded newline
 * would skew. */
static bool call_lint_path(const char* const* paths, size_t path_count, size_t* result_count,
    char* err_out, size_t err_size)
{
    struct Buffer* lint_paths = NULL;
    struct Buffer** lint_path_ptrs = NULL;
    uint8_t* buffer = NULL;
    uint8_t* result_buffer = NULL;
    bool status = false;
    if (path_count > 0) {
        lint_paths = (struct Buffer*)malloc(path_count * sizeof(struct Buffer));
        lint_path_ptrs = (struct Buffer**)malloc(path_count * sizeof(struct Buffer*));
        if (lint_paths == NULL || lint_path_ptrs == NULL)
            goto done;
        for (size_t i = 0; i < path_count; ++i) {
            lint_paths[i].buffer = paths[i];
            lint_paths[i].len = strlen(paths[i]);
            lint_path_ptrs[i] = &lint_paths[i];
        }
    }
    buffer = (uint8_t*)malloc(BUFFER_SIZE);
    result_buffer = (uint8_t*)malloc(BUFFER_SIZE);
    if (buffer == NULL || result_buffer == NULL)
        goto done;

    struct RepeatedString strs = { .repeated = lint_path_ptrs, .index = 0, .saved_index = 0, .max_size = path_count };
    LintPathArgs lint_args = LintPathArgs_init_zero;
    lint_args.paths.funcs.encode = encode_str_list;
    lint_args.paths.arg = &strs;

    pb_ostream_t stream = pb_ostream_from_buffer(buffer, BUFFER_SIZE);
    if (!pb_encode(&stream, LintPathArgs_fields, &lint_args))
        goto done;

    size_t result_length = kcl_call("KclService.LintPath", buffer, stream.bytes_written, result_buffer);
    if (check_error_prefix(result_buffer)) {
        kcl_copy_string(err_out, err_size, result_buffer);
        goto done;
    }

    pb_istream_t istream = pb_istream_from_buffer(result_buffer, result_length);
    LintPathResult result = LintPathResult_init_default;
    size_t count = 0;
    result.results.funcs.decode = kcl_decode_count_only;
    result.results.arg = &count;
    if (!pb_decode(&istream, LintPathResult_fields, &result))
        goto done;
    *result_count = count;
    status = true;

done:
    free(buffer);
    free(result_buffer);
    free(lint_paths);
    free(lint_path_ptrs);
    return status;
}

/* FormatTestReportArgs.result.info is a repeated TestCaseInfo; the wrapper
 * takes the same cases through struct KclTestCaseInfo. `line_hits` is not
 * part of that struct and the reporter does not render it — the manifest
 * pins it as an empty map for every case.
 */
static size_t json_test_cases(const kcl_json_value_t* args, struct KclTestCaseInfo* out, size_t max)
{
    const kcl_json_value_t* list = kcl_json_object_get(kcl_json_object_get(args, "result"), "info");
    size_t n = kcl_json_array_length(list);
    if (n > max)
        n = max;
    for (size_t i = 0; i < n; ++i) {
        const kcl_json_value_t* info = kcl_json_array_get(list, i);
        kcl_copy_string(out[i].name, sizeof(out[i].name), (const uint8_t*)json_field(info, "name", ""));
        kcl_copy_string(out[i].error, sizeof(out[i].error), (const uint8_t*)json_field(info, "error", ""));
        kcl_copy_string(out[i].log_message, sizeof(out[i].log_message), (const uint8_t*)json_field(info, "log_message", ""));
        out[i].duration = json_duration(kcl_json_object_get(info, "duration"));
    }
    return n;
}

static void free_fields(struct projected_field* fields, size_t field_count)
{
    for (size_t i = 0; i < field_count; ++i)
        kcl_json_free(fields[i].value);
}

static kcl_json_value_t* sorted_basenames_json(const char* newline_joined)
{
    kcl_json_value_t* lines = split_lines_json(newline_joined);
    kcl_json_value_t* names = jb_array();
    for (size_t i = 0; i < lines->u.array.count; ++i)
        jb_push(names, jb_string(path_basename(lines->u.array.items[i]->u.string.data)));
    sort_string_array(names);
    kcl_json_free(lines);
    return names;
}

/* Only the major.minor pair of the version is pinned: the patch moves
 * with every release, and the manifest is regenerated against a pinned
 * core. */
static const char* major_minor(const char* version, char* buf, size_t buf_size)
{
    const char* first = strchr(version, '.');
    const char* second;
    size_t len;
    if (first == NULL)
        return version;
    second = strchr(first + 1, '.');
    len = second != NULL ? (size_t)(second - version) : strlen(version);
    if (len >= buf_size)
        len = buf_size - 1;
    memcpy(buf, version, len);
    buf[len] = '\0';
    return buf;
}

/* True when `rpc` is one of the '\n'-joined names a ListMethod answer
 * carries. */
static bool method_available(const char* list, const char* rpc)
{
    size_t len = strlen(rpc);
    const char* cursor = list;
    while (*cursor != '\0') {
        const char* newline = strchr(cursor, '\n');
        size_t n = newline != NULL ? (size_t)(newline - cursor) : strlen(cursor);
        if (n == len && memcmp(cursor, rpc, len) == 0)
            return true;
        if (newline == NULL)
            break;
        cursor = newline + 1;
    }
    return false;
}

/* True when any line of a '\n'-joined collector buffer is empty — the
 * ListMethod case pins that no advertised name is the empty string. */
static bool has_empty_line(const char* text)
{
    const char* line = text;
    while (*line != '\0') {
        const char* eol = strchr(line, '\n');
        size_t len = eol != NULL ? (size_t)(eol - line) : strlen(line);
        if (len == 0)
            return true;
        line = eol != NULL ? eol + 1 : line + len;
    }
    return false;
}

/* ------------------------------------------------------------------ *
 * RPC dispatch                                                        *
 * ------------------------------------------------------------------ */

static enum case_status run_case(struct runner* r, const kcl_json_value_t* node)
{
    const char* name = json_field(node, "name", "<unnamed>");
    const char* rpc = json_field(node, "rpc", "");
    const kcl_json_value_t* args = kcl_json_object_get(node, "args");
    const kcl_json_value_t* expect = kcl_json_object_get(node, "expect");
    if (expect == NULL || expect->type != KCL_JSON_OBJECT) {
        printf("    case `%s` has no `expect` object\n", name);
        return CASE_FAIL;
    }

    struct projected_field fields[12];
    size_t field_count = 0;
    size_t count = 0;
    result_primary[0] = '\0';
    result_error[0] = '\0';
    bool call_ok = false;

    if (strcmp(rpc, "KclService.Ping") == 0) {
        call_ok = kcl_ping(json_field(args, "value", ""), result_primary, sizeof(result_primary));
        fields[field_count++] = (struct projected_field){ "value", jb_string(result_primary) };
    } else if (strcmp(rpc, "KclService.ExecProgram") == 0) {
        call_ok = call_exec_program(r, args, result_primary, sizeof(result_primary),
            result_secondary, sizeof(result_secondary), result_error, sizeof(result_error));
        fields[field_count++] = (struct projected_field){ "yaml_result", jb_string(result_primary) };
        fields[field_count++] = (struct projected_field){ "json_result", jb_string(result_secondary) };
    } else if (strcmp(rpc, "KclService.FormatCode") == 0) {
        call_ok = kcl_format_code(json_field(args, "source", ""), result_primary, sizeof(result_primary));
        fields[field_count++] = (struct projected_field){ "formatted", jb_string(result_primary) };
    } else if (strcmp(rpc, "KclService.ValidateCode") == 0) {
        bool valid = kcl_validate_code(json_field(args, "code", ""), json_field(args, "data", ""),
            result_primary, sizeof(result_primary));
        /* kcl_validate_code reports the RPC error through the same buffer,
         * so an ERROR prefix is the call failing; anything else is the
         * validator's diagnostic, with `valid` saying whether the data
         * validated. */
        call_ok = !check_error_prefix((uint8_t*)result_primary);
        fields[field_count++] = (struct projected_field){ "success", jb_bool(valid) };
        fields[field_count++] = (struct projected_field){ "err_message", jb_string(result_primary) };
        fields[field_count++] = (struct projected_field){ "has_error_message", jb_bool(result_primary[0] != '\0') };
    } else if (strcmp(rpc, "KclService.FormatTestReport") == 0) {
        size_t test_count = json_test_cases(args, test_cases, CONSISTENCY_MAX_LIST);
        call_ok = kcl_format_test_report(test_count > 0 ? test_cases : NULL, test_count,
            result_primary, sizeof(result_primary));
        fields[field_count++] = (struct projected_field){ "report", jb_string(result_primary) };
    } else if (strcmp(rpc, "KclService.GenerateToml") == 0) {
        struct KclExecProgramArgs request;
        if (!json_exec_args(r, kcl_json_object_get(args, "exec_args"), &request, work_dir_scratch, sizeof(work_dir_scratch)))
            goto args_failed;
        call_ok = kcl_generate_toml(&request, result_primary, sizeof(result_primary));
        fields[field_count++] = (struct projected_field){ "toml", jb_string(result_primary) };
    } else if (strcmp(rpc, "KclService.GenerateKcl") == 0) {
        call_ok = kcl_generate_kcl(json_field(args, "source", ""), json_field(args, "filename", ""),
            json_field(args, "format", ""), result_primary, sizeof(result_primary));
        fields[field_count++] = (struct projected_field){ "kcl", jb_string(result_primary) };
    } else if (strcmp(rpc, "KclService.GenerateOpenAPI") == 0) {
        struct KclParseProgramArgs request;
        if (!json_parse_args(r, kcl_json_object_get(args, "parse_args"), &request))
            goto args_failed;
        call_ok = kcl_generate_openapi(&request, json_field(args, "version", ""), result_primary, sizeof(result_primary));
        fields[field_count++] = (struct projected_field){ "spec", jb_string(result_primary) };
    } else if (strcmp(rpc, "KclService.GenerateProto") == 0) {
        struct KclParseProgramArgs request;
        if (!json_parse_args(r, kcl_json_object_get(args, "parse_args"), &request))
            goto args_failed;
        call_ok = kcl_generate_proto(&request, json_field(args, "package", ""), result_primary, sizeof(result_primary));
        fields[field_count++] = (struct projected_field){ "proto", jb_string(result_primary) };
    } else if (strcmp(rpc, "KclService.GenerateDoc") == 0) {
        struct KclParseProgramArgs request;
        if (!json_parse_args(r, kcl_json_object_get(args, "parse_args"), &request))
            goto args_failed;
        call_ok = kcl_generate_doc(&request, json_field(args, "format", ""), result_primary, sizeof(result_primary));
        fields[field_count++] = (struct projected_field){ "content", jb_string(result_primary) };
    } else if (strcmp(rpc, "KclService.ParseFile") == 0) {
        call_ok = call_parse_file(args, result_primary, sizeof(result_primary),
            collected_paths, sizeof(collected_paths), parse_errors_doc, sizeof(parse_errors_doc),
            result_error, sizeof(result_error));
        fields[field_count++] = (struct projected_field){ "body_count", jb_number((double)json_tree_len(result_primary, "body", NULL)) };
        fields[field_count++] = (struct projected_field){ "error_count", jb_number((double)json_array_count(parse_errors_doc)) };
        fields[field_count++] = (struct projected_field){ "deps", split_lines_json(collected_paths) };
    } else if (strcmp(rpc, "KclService.ParseProgram") == 0) {
        call_ok = call_parse_program(args, result_primary, sizeof(result_primary),
            collected_paths, sizeof(collected_paths), parse_errors_doc, sizeof(parse_errors_doc),
            result_error, sizeof(result_error));
        fields[field_count++] = (struct projected_field){ "module_count", jb_number((double)json_tree_len(result_primary, "pkgs", "__main__")) };
        fields[field_count++] = (struct projected_field){ "error_count", jb_number((double)json_array_count(parse_errors_doc)) };
        fields[field_count++] = (struct projected_field){ "paths", sorted_basenames_json(collected_paths) };
    } else if (strcmp(rpc, "KclService.ListOptions") == 0) {
        call_ok = call_list_options(args, &count, result_error, sizeof(result_error));
        kcl_json_value_t* options = jb_array();
        for (size_t i = 0; i < count; ++i) {
            kcl_json_value_t* pair = jb_array();
            jb_push(pair, jb_string(option_help[i].name));
            jb_push(pair, jb_bool(option_help[i].required));
            jb_push(options, pair);
        }
        qsort(options->u.array.items, options->u.array.count, sizeof(kcl_json_value_t*), compare_pair_items);
        fields[field_count++] = (struct projected_field){ "option_count", jb_number((double)count) };
        fields[field_count++] = (struct projected_field){ "options", options };
    } else if (strcmp(rpc, "KclService.ListVariables") == 0) {
        size_t file_count = json_resolved_paths(r, args, "files", plain_path_list, plain_path_scratch, CONSISTENCY_MAX_LIST);
        size_t spec_count = json_string_list(args, "specs", plain_spec_list, CONSISTENCY_MAX_LIST);
        struct KclListVariablesResult lv_result = {
            .variables = list_variables_doc,
            .variables_size = sizeof(list_variables_doc),
            .unsupported_codes = lv_unsupported_codes,
            .unsupported_codes_size = sizeof(lv_unsupported_codes),
            .parse_errors = lv_parse_errors,
            .parse_errors_size = sizeof(lv_parse_errors),
        };
        call_ok = kcl_list_variables(plain_path_list, file_count, plain_spec_list, spec_count, false,
            &lv_result, result_error, sizeof(result_error));
        fields[field_count++] = (struct projected_field){ "values", project_variable_values(list_variables_doc) };
        fields[field_count++] = (struct projected_field){ "unsupported_codes", split_lines_json(lv_unsupported_codes) };
        fields[field_count++] = (struct projected_field){ "parse_error_count", jb_number((double)json_array_count(lv_parse_errors)) };
    } else if (strcmp(rpc, "KclService.LoadPackage") == 0) {
        struct KclParseProgramArgs request;
        if (!json_parse_args(r, kcl_json_object_get(args, "parse_args"), &request))
            goto args_failed;
        load_package_result = (struct KclLoadPackageResult){
            .program = load_package_program,
            .program_size = sizeof(load_package_program),
            .paths = load_package_paths,
            .paths_size = sizeof(load_package_paths),
            .parse_errors = load_package_parse_errors,
            .parse_errors_size = sizeof(load_package_parse_errors),
            .type_errors = load_package_type_errors,
            .type_errors_size = sizeof(load_package_type_errors),
            .scopes = load_package_scopes,
            .scopes_size = sizeof(load_package_scopes),
            .symbols = load_package_symbols,
            .symbols_size = sizeof(load_package_symbols),
            .node_symbol_map = load_package_node_symbol_map,
            .node_symbol_map_size = sizeof(load_package_node_symbol_map),
            .symbol_node_map = load_package_symbol_node_map,
            .symbol_node_map_size = sizeof(load_package_symbol_node_map),
            .fully_qualified_name_map = load_package_fqn_map,
            .fully_qualified_name_map_size = sizeof(load_package_fqn_map),
            .pkg_scope_map = load_package_pkg_scope_map,
            .pkg_scope_map_size = sizeof(load_package_pkg_scope_map),
        };
        call_ok = kcl_load_package(request.paths, request.path_count,
            json_flag(args, "resolve_ast", false), json_flag(args, "load_builtin", false),
            json_flag(args, "with_ast_index", false), &load_package_result,
            result_error, sizeof(result_error));
        fields[field_count++] = (struct projected_field){ "path_count", jb_number((double)count_lines(load_package_paths)) };
        fields[field_count++] = (struct projected_field){ "type_error_count", jb_number((double)json_array_count(load_package_type_errors)) };
        fields[field_count++] = (struct projected_field){ "parse_error_count", jb_number((double)json_array_count(load_package_parse_errors)) };
        fields[field_count++] = (struct projected_field){ "symbol_count", jb_number((double)json_array_count(load_package_symbols)) };
        fields[field_count++] = (struct projected_field){ "scope_count", jb_number((double)json_array_count(load_package_scopes)) };
        fields[field_count++] = (struct projected_field){ "has_kcl_mod", jb_bool(load_package_result.has_kcl_mod) };
        fields[field_count++] = (struct projected_field){ "kcl_mod_name", jb_string(load_package_result.kcl_mod_name) };
        fields[field_count++] = (struct projected_field){ "app_count", jb_number((double)load_package_result.app_count) };
        fields[field_count++] = (struct projected_field){ "import_count", jb_number((double)load_package_result.import_count) };
    } else if (strcmp(rpc, "KclService.GetSchemaTypeMapping") == 0
        || strcmp(rpc, "KclService.GetSchemaTypeMappingUnderPath") == 0) {
        mapping_doc[0] = '\0';
        call_ok = call_schema_mapping(r, rpc, args, mapping_doc, sizeof(mapping_doc),
            result_error, sizeof(result_error));
        {
            kcl_json_value_t* rendered = mapping_doc[0] != '\0' ? kcl_json_parse(mapping_doc) : NULL;
            if (rendered != NULL) {
                fields[field_count++] = (struct projected_field){ "type_mapping", entries_to_object(rendered) };
                kcl_json_free(rendered);
            } else {
                fields[field_count++] = (struct projected_field){ "type_mapping", jb_object() };
            }
        }
    } else if (strcmp(rpc, "KclService.GetVersion") == 0) {
        call_ok = kcl_get_version(&version_result);
        {
            char version_buf[64];
            fields[field_count++] = (struct projected_field){ "version",
                jb_string(major_minor(version_result.version, version_buf, sizeof(version_buf))) };
        }
        fields[field_count++] = (struct projected_field){ "has_checksum", jb_bool(version_result.checksum[0] != '\0') };
        fields[field_count++] = (struct projected_field){ "has_git_sha", jb_bool(version_result.git_sha[0] != '\0') };
        fields[field_count++] = (struct projected_field){ "has_version_info", jb_bool(version_result.version_info[0] != '\0') };
    } else if (strcmp(rpc, "BuiltinService.ListMethod") == 0) {
        call_ok = kcl_list_method(method_list, sizeof(method_list));
        fields[field_count++] = (struct projected_field){ "has_kclservice_ping",
            jb_bool(method_available(method_list, "KclService.Ping")) };
        fields[field_count++] = (struct projected_field){ "has_kclservice_parse_program",
            jb_bool(method_available(method_list, "KclService.ParseProgram")) };
        fields[field_count++] = (struct projected_field){ "has_builtinservice_list_method",
            jb_bool(method_available(method_list, "BuiltinService.ListMethod")) };
        fields[field_count++] = (struct projected_field){ "method_count", jb_number((double)count_lines(method_list)) };
        fields[field_count++] = (struct projected_field){ "has_empty_name", jb_bool(has_empty_line(method_list)) };
    } else if (strcmp(rpc, "KclService.LintPath") == 0) {
        size_t path_count = json_resolved_paths(r, args, "paths", plain_path_list, plain_path_scratch, CONSISTENCY_MAX_LIST);
        call_ok = call_lint_path(plain_path_list, path_count, &count, result_error, sizeof(result_error));
        fields[field_count++] = (struct projected_field){ "result_count", jb_number((double)count) };
        fields[field_count++] = (struct projected_field){ "has_result", jb_bool(count > 0) };
    } else if (strcmp(rpc, "KclService.FormatPath") == 0) {
        const char* path = json_field(args, "path", "");
        const char* resolved = resolve_path(r, path, work_dir_scratch, sizeof(work_dir_scratch));
        if (resolved == NULL)
            goto args_failed;
        call_ok = kcl_format_path(resolved, json_flag(args, "dry_run", false),
            collected_paths, sizeof(collected_paths), result_error, sizeof(result_error));
        fields[field_count++] = (struct projected_field){ "changed_count", jb_number((double)count_lines(collected_paths)) };
        fields[field_count++] = (struct projected_field){ "changed", sorted_basenames_json(collected_paths) };
    } else if (strcmp(rpc, "KclService.Test") == 0) {
        size_t pkg_count = json_resolved_paths(r, args, "pkg_list", plain_path_list, plain_path_scratch, CONSISTENCY_MAX_LIST);
        call_ok = kcl_test(NULL, NULL, 0, plain_path_list, pkg_count, NULL, false,
            test_cases, CONSISTENCY_MAX_LIST, &count, result_error, sizeof(result_error));
        {
            kcl_json_value_t* names = jb_array();
            kcl_json_value_t* failed = jb_array();
            for (size_t i = 0; i < count; ++i) {
                jb_push(names, jb_string(test_cases[i].name));
                if (test_cases[i].error[0] != '\0')
                    jb_push(failed, jb_string(test_cases[i].name));
            }
            sort_string_array(names);
            sort_string_array(failed);
            fields[field_count++] = (struct projected_field){ "names", names };
            fields[field_count++] = (struct projected_field){ "failed", failed };
        }
    } else if (strcmp(rpc, "KclService.OverrideFile") == 0) {
        const char* file = json_field(args, "file", "");
        const char* resolved = resolve_path(r, file, work_dir_scratch, sizeof(work_dir_scratch));
        size_t spec_count;
        bool overridden = false;
        if (resolved == NULL)
            goto args_failed;
        spec_count = json_string_list(args, "specs", plain_spec_list, CONSISTENCY_MAX_LIST);
        parse_errors_doc[0] = '\0';
        call_ok = kcl_override_file(resolved, plain_spec_list, spec_count, NULL, 0,
            &overridden, parse_errors_doc, sizeof(parse_errors_doc), result_error, sizeof(result_error));
        fields[field_count++] = (struct projected_field){ "result", jb_bool(overridden) };
        fields[field_count++] = (struct projected_field){ "parse_error_count", jb_number((double)json_array_count(parse_errors_doc)) };
    } else if (strcmp(rpc, "KclService.LoadSettingsFiles") == 0) {
        const char* work_dir = json_field(args, "work_dir", "");
        const char* resolved_dir = resolve_path(r, work_dir, work_dir_scratch, sizeof(work_dir_scratch));
        size_t file_count;
        if (resolved_dir == NULL)
            goto args_failed;
        file_count = json_resolved_paths(r, args, "files", plain_path_list, plain_path_scratch, CONSISTENCY_MAX_LIST);
        settings_result = (struct KclLoadSettingsFilesResult){
            .kcl_options = settings_options,
            .kcl_options_size = CONSISTENCY_MAX_LIST,
        };
        call_ok = kcl_load_settings_files(resolved_dir, plain_path_list, file_count,
            &settings_result, result_error, sizeof(result_error));
        {
            kcl_json_value_t* options = jb_array();
            for (size_t i = 0; i < settings_result.kcl_option_count; ++i) {
                kcl_json_value_t* pair = jb_array();
                jb_push(pair, jb_string(settings_options[i].key));
                jb_push(pair, jb_string(settings_options[i].value));
                jb_push(options, pair);
            }
            qsort(options->u.array.items, options->u.array.count, sizeof(kcl_json_value_t*), compare_pair_items);
            fields[field_count++] = (struct projected_field){ "options", options };
        }
        fields[field_count++] = (struct projected_field){ "output", jb_string(settings_result.kcl_cli_configs.output) };
        fields[field_count++] = (struct projected_field){ "overrides", split_lines_json(settings_result.kcl_cli_configs.overrides) };
        fields[field_count++] = (struct projected_field){ "strict_range_check", jb_bool(settings_result.kcl_cli_configs.strict_range_check) };
        fields[field_count++] = (struct projected_field){ "verbose", jb_number((double)settings_result.kcl_cli_configs.verbose) };
    } else if (strcmp(rpc, "KclService.UpdateDependencies") == 0) {
        const char* manifest_path = json_field(args, "manifest_path", "");
        const char* resolved = resolve_path(r, manifest_path, work_dir_scratch, sizeof(work_dir_scratch));
        if (resolved == NULL)
            goto args_failed;
        call_ok = kcl_update_dependencies(resolved, json_flag(args, "vendor", false),
            dep_pkgs, CONSISTENCY_MAX_LIST, &count, result_error, sizeof(result_error));
        fields[field_count++] = (struct projected_field){ "external_pkg_count", jb_number((double)count) };
    } else {
        printf("    no C runner support for rpc `%s`\n", rpc);
        return CASE_FAIL;
    }

    if (!call_ok) {
        /* A wrapper copies the `ERROR:` reply into its error buffer, so
         * the message is whichever result buffer the rpc wrote to. */
        const char* message = result_error[0] != '\0' ? result_error : result_primary;
        if (json_flag(node, "new_core", false) && is_unavailable_rpc_error(message)) {
            r->skip_reason = "the core does not implement the rpc";
            free_fields(fields, field_count);
            return CASE_SKIP;
        }
        printf("    %s failed: %s\n", rpc, message);
        free_fields(fields, field_count);
        return CASE_FAIL;
    }

    {
        enum case_status status = compare_fields(name, expect, fields, field_count,
                              expect_render, sizeof(expect_render),
                              actual_render, sizeof(actual_render))
            ? CASE_PASS
            : CASE_FAIL;
        free_fields(fields, field_count);
        return status;
    }

args_failed:
    printf("    case `%s`: could not resolve the args paths (scratch copy failed?)\n", name);
    free_fields(fields, field_count);
    return CASE_FAIL;
}

/* ------------------------------------------------------------------ *
 * Entry point                                                         *
 * ------------------------------------------------------------------ */

static bool string_in_list(const char* text, const char* const* list, size_t list_count)
{
    for (size_t i = 0; i < list_count; ++i) {
        if (strcmp(text, list[i]) == 0)
            return true;
    }
    return false;
}

int main()
{
    struct runner r = { 0 };
    char manifest_path[PATH_MAX];
    bool located = false;
    for (size_t i = 0; i < sizeof(MANIFEST_CANDIDATES) / sizeof(MANIFEST_CANDIDATES[0]); ++i) {
        if (realpath(MANIFEST_CANDIDATES[i], manifest_path) != NULL) {
            located = true;
            break;
        }
    }
    if (!located) {
        printf("consistency manifest not found; run `python tests/consistency/generate_cases.py` to generate it\n");
        return 1;
    }

    /* The repository root is the parent of the parent of the directory
     * holding cases.json, which is what the manifest's repo-relative paths
     * are pinned against. Walking `end` backwards one separator at a time
     * strips cases.json, then consistency, then tests — searching from
     * `manifest_path` each round rather than from the previous separator,
     * which would otherwise re-match it. */
    const char* end = manifest_path + strlen(manifest_path);
    for (int level = 0; level < 3; ++level) {
        const char* slash = NULL;
        for (const char* p = manifest_path; p < end; ++p) {
            if (*p == '/')
                slash = p;
        }
        if (slash == NULL) {
            printf("cannot derive the repository root from %s\n", manifest_path);
            return 1;
        }
        end = slash;
    }
    size_t root_len = (size_t)(end - manifest_path);
    if (root_len == 0 || root_len + 1 > sizeof(r.repo_root)) {
        printf("repository root does not fit in %zu bytes\n", sizeof(r.repo_root));
        return 1;
    }
    memcpy(r.repo_root, manifest_path, root_len);
    r.repo_root[root_len] = '\0';

    FILE* file = fopen(manifest_path, "rb");
    if (file == NULL) {
        printf("cannot open %s\n", manifest_path);
        return 1;
    }
    if (fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        printf("cannot seek %s\n", manifest_path);
        return 1;
    }
    long manifest_size = ftell(file);
    rewind(file);
    if (manifest_size < 0) {
        fclose(file);
        printf("cannot size %s\n", manifest_path);
        return 1;
    }
    char* manifest_text = (char*)malloc((size_t)manifest_size + 1);
    if (manifest_text == NULL) {
        fclose(file);
        printf("out of memory reading %s\n", manifest_path);
        return 1;
    }
    size_t read = fread(manifest_text, 1, (size_t)manifest_size, file);
    fclose(file);
    manifest_text[read] = '\0';

    kcl_json_value_t* manifest = kcl_json_parse(manifest_text);
    free(manifest_text);
    if (manifest == NULL) {
        printf("failed to parse %s\n", manifest_path);
        return 1;
    }

    const kcl_json_value_t* version = kcl_json_object_get(manifest, "version");
    if (version == NULL || version->type != KCL_JSON_NUMBER || (int)version->u.number != 1) {
        printf("unsupported consistency manifest version\n");
        kcl_json_free(manifest);
        return 1;
    }

    const kcl_json_value_t* cases = kcl_json_object_get(manifest, "cases");
    size_t case_count = kcl_json_array_length(cases);
    if (case_count == 0) {
        printf("consistency manifest has no cases\n");
        kcl_json_free(manifest);
        return 1;
    }

    /* Determine the core's RPC surface once per run. Cores that predate
     * BuiltinService.ListMethod answer with an empty list, in which case
     * every `new_core` case is skipped. */
    r.methods_known = kcl_list_method(method_list, sizeof(method_list));
    r.methods = method_list;

    printf("consistency manifest: %s\n", manifest_path);
    printf("repository root:      %s\n", r.repo_root);
    printf("core RPC surface:     %s\n", r.methods_known ? "available" : "unavailable (new_core cases will be skipped)");

    for (size_t i = 0; i < case_count; ++i) {
        const kcl_json_value_t* node = kcl_json_array_get(cases, i);
        const char* name = json_field(node, "name", "<unnamed>");
        const char* rpc = json_field(node, "rpc", "");
        r.skip_reason = NULL;

        if (json_flag(node, "new_core", false)
            && (!r.methods_known || !method_available(r.methods, rpc))) {
            r.skipped++;
            printf("SKIP %-24s core does not list %s (old core)\n", name, rpc);
            continue;
        }

        switch (run_case(&r, node)) {
        case CASE_PASS:
            r.passed++;
            printf("PASS %s\n", name);
            break;
        case CASE_SKIP:
            r.skipped++;
            printf("SKIP %-24s %s\n", name, r.skip_reason != NULL ? r.skip_reason : "skipped");
            break;
        case CASE_FAIL:
        default:
            r.failed++;
            printf("FAIL %s\n", name);
            break;
        }
        /* Scratch copies only live for the case that made them; take
         * them down passed, failed or skipped so a run leaves nothing
         * behind in the temp directory. */
        cleanup_scratch();
    }

    /* Coverage guard, mirroring the sibling ports: the manifest is the
     * contract, so a case it lists that this file does not dispatch is a
     * failure — as is a dispatched name the manifest no longer lists,
     * which catches a typoed entry quietly testing nothing. The check
     * reads DISPATCHED_CASES rather than anything recorded at run time,
     * so it cannot agree with itself. */
    for (size_t i = 0; i < case_count; ++i) {
        const kcl_json_value_t* node = kcl_json_array_get(cases, i);
        const char* name = json_field(node, "name", "<unnamed>");
        if (!string_in_list(name, DISPATCHED_CASES, sizeof(DISPATCHED_CASES) / sizeof(DISPATCHED_CASES[0]))) {
            printf("manifest case `%s` is not in DISPATCHED_CASES; add a dispatch branch for it\n", name);
            r.failed++;
        }
    }
    for (size_t i = 0; i < sizeof(DISPATCHED_CASES) / sizeof(DISPATCHED_CASES[0]); ++i) {
        bool found = false;
        for (size_t j = 0; j < case_count; ++j) {
            const kcl_json_value_t* node = kcl_json_array_get(cases, j);
            if (strcmp(json_field(node, "name", "<unnamed>"), DISPATCHED_CASES[i]) == 0) {
                found = true;
                break;
            }
        }
        if (!found) {
            printf("DISPATCHED_CASES entry `%s` is not in the manifest; remove the stale dispatch branch\n", DISPATCHED_CASES[i]);
            r.failed++;
        }
    }

    printf("\n%zu passed, %zu failed, %zu skipped (of %zu cases)\n",
        r.passed, r.failed, r.skipped, case_count);
    kcl_json_free(manifest);
    return r.failed == 0 ? 0 : 1;
}
